set search_path=public,extensions;
select plan(37);
select public.configure_private_owner('owner-test@example.com');
insert into auth.users(id,email,aud,role,email_confirmed_at,created_at,updated_at) values('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','owner-test@example.com','authenticated','authenticated',now(),now(),now());
